% BCWT, April 18 2017%% Re-hash of the two filament code (basic co-linear thick and thin% filaments) for 20 myosin cross-bridges spaced 42.9 nm apart along a row% and 30 binding sites along the thin filament spaced 37.3 nm apart along a% row.  These two-rows of sites face eachother.  There is only movement or% forces balanced in 1 dimension.  All very similar, consistent with the% Daniel et al. Biophyiscal Journal manuscript published in 1998.%% Note, I stripped off the calcium regulation and cooperative activation of% neighboring filaments within this set of files too.  Just basic force% production based on proximity to a binding site, and the chemo-mechanical% Monte Carlo algorithms driving the kinetics.CurrentDir=pwd; % Gather our current working directory, for future use if% we want to use this to write out the data files for position,% cross-bridge states, thin filameent states (when we get Ca2+ regulation)clear all;tic;  % Start the clock on runtimeTwofilparams;  % Load the parameter set function% Build the basic 'mcore' matrix of spring constants, before there is any% cross-bridge binding.  This will be modified as XB bind with BS, and the% matrix will be populated each timestep, accordingly.mcore = Build_mcore( NN, nXB, km, kms, nBS, ka, kas );% initialize all average stats (these will be used to calculate the total% average of each set of runs)for it = 1:nsteps    t(it) = it*dt; %% Define Time    fmean(it) = 0.0; %% Initialize all mean force = 0 for all timesteps    fractbound(it) = 0.0; %% Initialize all mean force = 0 for all timesteps        for ii = 1:NN  %Keeps track of the mean for each sight at each time        meanstate(ii,it) = 0.0; %% Currently not used (BCWT, April 17 2017)        meanx(ii,it) = 0.0; %% Currently not used (BCWT, April 17 2017)        meany(ii,it) = 0.0; %% Currently not used (BCWT, April 17 2017)        meanxb(ii,it) = 0.0; %% Currently not used (BCWT, April 17 2017)    end    endATPmean = 0.0; %% Initialize -- not sure why this isn't a vector as fmeanATP = 0.0; %dl = 0.0; %% dl--if changing length of sarcomere (can be vector or change each dt)for iRuns = 1:nruns % Right now 25    % Loop over all XB and BS    for ii=1:NN  %Initialize the Vectors and states for each run.        A(ii) = 0.0;        xbstate(ii) = 1;        site(ii) = 0.0;        xbx(ii) = 0.0;        xbk(ii) = 0.0;    end        for jj = nXB+1:NN  % of which the 1st 20 spots will be empty        occupied(jj) = 0; %% Currently not used (BCWT, April 17 2017)    end        for it = 1:nsteps                m = mcore;        for ii = 1:NN A(ii) = 0.0; end                for ii = 1:nXB  % For each head location            if site(ii) > 0  %If the head is bound                %(where site is a vector nXB+nBS long that holds                % the index of which BS it is bound with to keep                % track of binding pairs--but note some issues here as                % site(1:nXB) is only populated                                % Below, modify the matrix of spring contants for XB and BS                % binding pairs, by adding in the kxb as needed, and also                % for the A (A=end vector of boundary conditions).                m(ii,ii) = mcore(ii,ii) - xbk(ii);                m(ii,site(ii)) = mcore(ii,site(ii)) + xbk(ii);                m(site(ii),ii) = mcore(site(ii),ii) + xbk(ii);                m(site(ii),site(ii)) = mcore(site(ii),site(ii)) - xbk(ii);                A(ii) = xbx(ii)*xbk(ii);                A(site(ii)) = -xbx(ii)*xbk(ii);            end        end                dl = 0.0;                % Initialize the A vector for the BCs with thick and thin        % This could go in the Build_Mcore function too, and return it, but        % kept here if dl (=change in half SL length) were wanting to be fiddled        % with easily (dynamic lengthen or shorten).        A(1) = A(1) + km*myspace - kms*yo;        A(nXB) = A(nXB) - km*myspace;        A(nXB+1) = A(nXB+1) + ka*acspace;        A(NN) = A(NN) - acspace*ka - kas*(xo + nBS*acspace + dl);                %so now we have a matrix equation        %  K.x + A = 0, or really m*X + A = 0 with our variables        X = A/m;    %  the vector of all xb and BS locations        for i = 1:nXB ym(i) = X(1,i); end    %  cross bridge locations        for i = nXB+1:NN  xa(i) = X(1,i); end  % binding site locations        force(it) = (X(1) - yo)*kms;    % end force -- because the force total will be        % equal to that tension on the first head, which will be represted        % as a hookean with the difference in position from orignial given        % above.                % Running average on mean force at (it) over nruns        fmean(it) = force(it)/nruns + fmean(it);        nbound = 0;        for i = 1:nXB            if (xbstate(i) > 1) nbound = nbound + 1; end        end        % Average Fractional XB binding        fractbound(it) = fractbound(it) + 1.0*nbound/(nruns*nXB);                %   now  find nearest neighbors and querry current states        for ii = 1:nXB            switch xbstate(ii)                case 1 %% Case 1 = not bound                    xbk(ii) = 0.0;                    xkx(ii) = 0.0;                    site(ii) = 0.0;                    % find nearest binding site                    %  nead to assess whether occupied div = 1;                    dist = abs(ym(ii) - xa);                                        dmin = min(dist); % find minimu distance for XB to BS                    siteindx = find(dist == dmin);   % index of nearest site                                        %find the rates for that distortion                    [k12,k21,k23,k32,k31,k13] = krates(dmin,reach,kRT,phos);                                        % use k12 and k13 to calculated probabilities based                    % on Monte Carlo with dt.                    p12 = dt*k12;                    p13 = dt*k13;                                        gx = rand;  % pull uniform random number (seed this?)                                        % Compute whether you switch state, based on                     % forward and reverse transition likelihoods                    if (gx <= p12)                        xbstate(ii) = 2;                        xbk(ii) = k2;                        %%%%%%%    \/                        xbx(ii) = dmin - reach;  %  this needs a fix ?                        site(ii) = siteindx;                    end                    if (gx >= 1.0 - p13)                        xbstate(ii) = 3.0;                        xbk(ii) = k2;                        xbx = 0.0;                        site(ii) = siteindx;                    end                                    case 2 % Case 2 = weakly bound, or low-force bound,                        % or bound (xo+reach)                    xbk(ii) = k2;                    dmin = xa(site(ii)) - ym(ii);                    xbx(ii) = dmin - reach;                    [k12,k21,k23,k32,k31,k13] = krates(dmin,reach,kRT,phos);                    p23 = dt*k23;                    p21 = dt*k21;                    gx = rand;                    % computer forward and reverse transition likelihoods                    if (gx <= p23)                        xbstate(ii) = 3;                        xbk(ii) = k2;                        xbx(ii) = 0.0;                    end                    if (gx >= (1.0 - p21))                        xbstate(ii) = 1;                        xbk(ii) = 0.0;                        xbx(ii) = 0.0;                    end                                    case 3 % Case 3 = strongly bound, or high-force bound,                        % or bound (xo)                    xbk(ii) = k2;                    dmin = xa(site(ii)) - ym(ii);                    xbx(ii) = dmin;                    [k12,k21,k23,k32,k31,k13] = krates(dmin,reach,kRT,phos);                    p31 = dt*k31;                    p32 = dt*k32;                    gx = rand;                    % computer forward and reverse transition likelihoods                    if (gx <= p31)                        xbstate(ii) = 1;                        xbk(ii) = 0.0;                        xbx(ii) = 0.0;                        ATP = ATP + 1; % Complete cycle, update ATP used                    end                    if (gx >= (1.0 - p32))                        xbstate(ii) = 2;                        xbk(ii) = k2;                        xbx(ii) = reach;                    end                                                    end  % end switch (state scan)                    end % end site scan (for each XB)            end  %time stepsend  %nrunstocDataIn=fmean;[asym, t_half, yout]=ExpFit(t', DataIn', 100, 2);close all; figure(2); set(gca,'nextplot','add'); plot(t,fmean,'b-', t, yout, 'k-');xmin=0; xmax=max(t); ymin=0; ymax=1.1*asym;axis([xmin, xmax, ymin, ymax])text(0.4*xmax, 0.4*ymax, 'Exp. Fit:')text(0.4*xmax, 0.35*ymax, ['Aympt. = ' num2str(asym) ])text(0.4*xmax, 0.3*ymax, ['Rate 1/2 Max = ' num2str(t_half) ])xlabel('Time (s)')ylabel('mean F (pN)')title(['No Ca regulation, nRuns = ' num2str(nruns) ', TwofilMC.m ' date])% OutDir='C:\Documents and Settings\danielab\Desktop\Bert\Twofil_Figs\';% OutFileID='unRegF';% saveas(gcf,[OutDir  OutFileID '.fig'],'fig');% saveas(gcf,[OutDir  OutFileID '.tif'],'tif');% saveas(gcf,[OutDir  OutFileID '.eps'],'eps');DataIn=fractbound;clear asym t_half yout[asym, t_half, yout]=ExpFit(t', DataIn', 100, 2);figure(3)plot(t, fractbound, 'b-', t, yout, 'k-');xmin=0; xmax=max(t); ymin=0; ymax=1.1*asym;axis([xmin, xmax, ymin, ymax])text(0.4*xmax, 0.4*ymax, 'Exp. Fit:')text(0.4*xmax, 0.35*ymax, ['Aympt. = ' num2str(asym) ])text(0.4*xmax, 0.3*ymax, ['Rate 1/2 Max = ' num2str(t_half) ])xlabel('Time (s)')ylabel('mean fraction heads bound')title(['No Ca regulation, nRuns = ' num2str(nruns) ', TwofilMC.m ' date])% OutDir='C:\Documents and Settings\danielab\Desktop\Bert\Twofil_Figs\';% OutFileID='unRegFB';% saveas(gcf,[OutDir  OutFileID '.fig'],'fig');% saveas(gcf,[OutDir  OutFileID '.tif'],'tif');% saveas(gcf,[OutDir  OutFileID '.eps'],'eps');